using System.ComponentModel.Composition;
using XrmToolBox.Extensibility;
using XrmToolBox.Extensibility.Interfaces;

namespace AuditHistoryExtractorPro.XrmToolBox.Plugin
{
    /// <summary>
    /// Punto de entrada MEF real del plugin para el host de XrmToolBox. El host compone el
    /// catálogo buscando exports de <see cref="IXrmToolBoxPlugin"/> — por eso el atributo va
    /// acá y no en <see cref="PluginControl"/> (el UserControl no implementa esa interfaz,
    /// implementa <c>IXrmToolBoxPluginControl</c> vía <c>PluginControlBase</c>; ponerle el
    /// Export directo al UserControl hace que el host descarte el plugin en silencio al no
    /// satisfacer el contrato exportado).
    /// </summary>
    /// <remarks>
    /// SmallImageBase64/BigImageBase64 NO pueden quedar vacíos: el host, al materializar
    /// Plugins\manifest.json (PluginMetadata), intenta decodificar esas imágenes para armar el
    /// tile — con "" tira una excepción de imagen inválida que el host atrapa en silencio y
    /// descarta el plugin (queda en ScannedAssemblies pero nunca en PluginMetadata, por eso no
    /// aparece en la UI aunque la composición MEF sea correcta). Bug real detectado 2026-09-04
    /// comparando Plugins\manifest.json contra otros plugins instalados.
    ///
    /// SecondaryFontColor tampoco puede faltar: de los 371 plugins reales instalados, las 371
    /// entradas de PluginMetadata tienen ese campo seteado (ninguna vacía) — el host arma el
    /// export vía una vista de metadata tipada (MEF) que exige esa propiedad; sin ella, el
    /// export queda excluido en silencio de esa consulta aunque siga viéndose bien en una
    /// consulta MEF sin vista de metadata (por eso las pruebas anteriores no lo detectaban).
    /// Segundo bug real, mismo día, mismo síntoma.
    /// </remarks>
    [Export(typeof(IXrmToolBoxPlugin))]
    [ExportMetadata("Name", "Audit History Extractor Pro")]
    [ExportMetadata("Description", "Extrae, exporta y valida historial de auditoría de Dataverse bajo demanda.")]
    [ExportMetadata("BackgroundColor", "White")]
    [ExportMetadata("PrimaryFontColor", "Black")]
    [ExportMetadata("SecondaryFontColor", "Gray")]
    [ExportMetadata("SmallImageBase64", "")]
    [ExportMetadata("BigImageBase64", "")]
    public class Plugin : PluginBase
    {
        public override IXrmToolBoxPluginControl GetControl() => new PluginControl();
    }
}
